/*
 * Copyright (c) 2023, Salesforce, Inc.
 * All rights reserved.
 * SPDX-License-Identifier: BSD-3-Clause
 * For full license text, see the LICENSE file in the repo root or https://opensource.org/licenses/BSD-3-Clause
 */

// Zimmermann storefronts — merged from two sources:
//   config/sites.generated.js — SCAPI-sourced locale/currency truth,
//     regenerate via `npm run sync:regional-config` (auto-generated, do not
//     hand-edit).
//   config/sites.overlay.js — hand-maintained routing data (URL alias,
//     sfccSiteId override) that Business Manager/SCAPI has no concept of.
// See .docs/prd/regional.md for routing rules; see
// .docs/planning/regionalConfigSyncPlan.md for why this is split this way.
/* eslint-disable @typescript-eslint/no-var-requires */
const generated = require('./sites.generated');
const overlay = require('./sites.overlay');

module.exports = overlay.map(({ id, sfccSiteId, locales }) => {
  const sourceId = sfccSiteId ?? id;
  const source = generated[sourceId];
  if (!source) {
    throw new Error(
      `config/sites.overlay.js references SFCC site '${sourceId}' (for PWA site '${id}') but ` +
        `config/sites.generated.js has no data for it. Run \`npm run sync:regional-config\`.`,
    );
  }
  return {
    id,
    ...(sfccSiteId ? { sfccSiteId } : {}),
    l10n: {
      supportedCurrencies: source.supportedCurrencies,
      defaultCurrency: source.defaultCurrency,
      // NOT source.defaultLocale — that's SCAPI's site-level default for the
      // real SFCC site, which can be a locale this PWA site doesn't even
      // support (e.g. BM's ZimmermannAU default is 'en-AU', but this PWA
      // site's overlay only lists 'en'; BM's ZimmermannEU default 'en-GB'
      // would wrongly apply to the EUfr/EUit/EUes PWA sites too, since all 4
      // share one real SFCC site). Every PWA site has exactly one locale in
      // its overlay, so that locale IS its default, full stop.
      defaultLocale: locales[0].id,
      supportedLocales: locales.map(({ id: localeId, alias }) => {
        const match = source.supportedLocales.find((l) => l.id === localeId);
        if (!match) {
          throw new Error(
            `config/sites.overlay.js declares locale '${localeId}' for site '${id}' but SFCC site ` +
              `'${sourceId}' does not support it per the latest sync. Run \`npm run sync:regional-config\` ` +
              `or check Business Manager.`,
          );
        }
        return { id: localeId, ...(alias ? { alias } : {}), preferredCurrency: match.preferredCurrency };
      }),
    },
  };
});

/*
 * Copyright (c) 2023, Salesforce, Inc.
 * All rights reserved.
 * SPDX-License-Identifier: BSD-3-Clause
 * For full license text, see the LICENSE file in the repo root or https://opensource.org/licenses/BSD-3-Clause
 */
/* eslint-disable @typescript-eslint/no-var-requires */

// Load .env (at repo root) into process.env (no dotenv dependency needed).
// Variables already set in the shell environment take precedence.
const fs = require('fs');
const path = require('path');
try {
  const envLines = fs.readFileSync(path.join(process.cwd(), '.env'), 'utf8').split('\n');
  for (const line of envLines) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue;
    const eqIdx = trimmed.indexOf('=');
    if (eqIdx === -1) continue;
    const key = trimmed.slice(0, eqIdx).trim();
    const value = trimmed.slice(eqIdx + 1).trim();
    if (key && !(key in process.env)) {
      process.env[key] = value;
    }
  }
} catch (_) {
  // .env is optional — no-op if absent
}

const sites = require('./sites.js');
const { parseSettings, validateOtpTokenLength } = require('./utils.js');

// SFCC-742 — ephemeral MRT preview targets (deploy-preview.yml, always prefixed `pr-` per
// scripts/computeMrtPreviewSlug.mjs) have no `config/${DEPLOY_TARGET}.js` of their own, so
// pwa-kit-runtime's getConfig() falls through to this file instead of config/dev.js. Without
// this, passwordless/social login silently render as disabled on every PR preview even though
// dev.js (and every named tier) already enables them — treat a preview target as dev for this
// flag, matching how deploy-preview.yml already sources its env vars and proxy config from dev.
const IS_PREVIEW_TARGET = Boolean(process.env.DEPLOY_TARGET?.startsWith('pr-'));

module.exports = {
  app: {
    // Enable the store locator and shop the store feature.
    storeLocatorEnabled: true,
    // Enable the multi-ship feature.
    multishipEnabled: true,
    // Enable partial hydration capabilities via Island component
    partialHydrationEnabled: false,
    // Commerce shopping agent configuration for embedded messaging service
    // This enables an agentic shopping experience in the application
    // This property accepts either a JSON string or a plain JavaScript object.
    commerceAgent: parseSettings(process.env.COMMERCE_AGENT_SETTINGS) || {
      enabled: 'false',
      askAgentOnSearch: 'false',
      embeddedServiceName: '',
      embeddedServiceEndpoint: '',
      scriptSourceUrl: '',
      scrt2Url: '',
      salesforceOrgId: '',
      commerceOrgId: '',
      siteId: '',
      enableConversationContext: 'false',
      conversationContext: [],
      enableAgentFromHeader: 'false',
      enableAgentFromFloatingButton: 'false',
      enableAgentFromSearchSuggestions: 'false',
    },
    // Customize how your 'site' and 'locale' are displayed in the url.
    url: {
      // Determine where the siteRef is located. Valid values include 'path|query_param|none'. Defaults to: 'none'
      site: 'path',
      // Determine where the localeRef is located. Valid values include 'path|query_param|none'. Defaults to: 'none'
      locale: 'path',
      // This boolean value dictates whether or not default site or locale values are shown in the url. Defaults to: false
      showDefaults: false,
      // This boolean value dictates whether or not the base path, defined in ssrParameters.envBasePath,
      // is shown in shopper facing urls. Defaults to: false
      showBasePath: false,
      // This boolean value dictates whether the plus sign (+) is interpreted as space for query param string. Defaults to: false
      interpretPlusSignAsSpace: false,
    },
    login: {
      // The length of the token for OTP authentication. Used by passwordless login and reset password.
      // If the env var `OTP_TOKEN_LENGTH` is set, it will override the config value. Valid values are 6 or 8. Defaults to: 8
      tokenLength: validateOtpTokenLength(process.env.OTP_TOKEN_LENGTH),
      passwordless: {
        // Enables or disables passwordless login for the site. Defaults to: false
        // (true on ephemeral pr-* preview targets — see IS_PREVIEW_TARGET above)
        enabled: IS_PREVIEW_TARGET,
        // The mode for passwordless login. Valid values include 'email|callback'. Defaults to: 'callback'
        mode: 'email',
        // The callback URI, which can be an absolute URL (including third-party URIs) or a relative path set up by the developer.
        // Required when mode is set to 'callback'. If the env var `PASSWORDLESS_LOGIN_CALLBACK_URI` is set, it will override the config value.
        // callbackURI:
        //     process.env.PASSWORDLESS_LOGIN_CALLBACK_URI || '/passwordless-login-callback',
        // The landing path for passwordless login
        landingPath: '/passwordless-login-landing',
      },
      social: {
        // Enables or disables social login for the site. Defaults to: false
        // (true on ephemeral pr-* preview targets — see IS_PREVIEW_TARGET above)
        enabled: IS_PREVIEW_TARGET,
        // The third-party identity providers supported by your app. The PWA Kit supports Google and Apple by default.
        // Additional IDPs will also need to be added to the IDP_CONFIG in the SocialLogin component.
        idps: ['google', 'apple'],
        // The redirect URI used after a successful social login authentication.
        // This should be a relative path set up by the developer.
        // If the env var `SOCIAL_LOGIN_REDIRECT_URI` is set, it will override the config value.
        redirectURI: process.env.SOCIAL_LOGIN_REDIRECT_URI || '/social-callback',
      },
      resetPassword: {
        // The mode for reset password. Valid values include 'email|callback'. Defaults to: 'callback'
        mode: 'email',
        // The callback URI, which can be an absolute URL (including third-party URIs) or a relative path set up by the developer.
        // Required when mode is set to 'callback'. If the env var `RESET_PASSWORD_CALLBACK_URI` is set, it will override the config value.
        // callbackURI: process.env.RESET_PASSWORD_CALLBACK_URI || '/reset-password-callback',
        // The landing path for reset password
        landingPath: '/reset-password-landing',
      },
    },
    // The default site for your app. This value will be used when a siteRef could not be determined from the url
    defaultSite: 'ZimmermannAU',
    // Provide aliases for your sites. These will be used in place of your site id when generating paths throughout the application.
    // AU has no alias — it is the defaultSite and showDefaults: false keeps it at the root (/).
    siteAliases: {
      ZimmermannUK: 'uk',
      ZimmermannUS: 'us',
      ZimmermannUSIntl: 'en-ca',
      // EU domestic: one PWA site per locale prefix — all backed by SFCC ZimmermannEU (see sites.js)
      ZimmermannEUen: 'en-eu',
      ZimmermannEUfr: 'fr-eu',
      ZimmermannEUit: 'it-eu',
      ZimmermannEUes: 'es-eu',
      ZimmermannEUIntl: 'en-ch',
      ZimmermannHK: 'hk',
      ZimmermannME: 'en-ae',
    },
    // The sites for your app, which is imported from sites.js
    sites,
    // Commerce api config
    commerceAPI: {
      proxyPath: '/mobify/proxy/api',
      parameters: {
        clientId: process.env.COMMERCE_API_CLIENT_ID,
        organizationId: process.env.COMMERCE_API_ORGANIZATION_ID,
        shortCode: process.env.COMMERCE_API_SHORT_CODE,
        siteId: process.env.COMMERCE_API_SITE_ID,
      },
    },
    // Einstein api config
    einsteinAPI: {
      host: 'https://api.cquotient.com',
      einsteinId: '1ea06c6e-c936-4324-bcf0-fada93f83bb1',
      siteId: process.env.EINSTEIN_API_SITE_ID,
      // Flag Einstein activities as coming from a production environment.
      // By setting this to true, the Einstein activities generated by the environment will appear
      // in production environment reports
      isProduction: false,
    },
    // Datacloud api config
    dataCloudAPI: {
      appSourceId: '7ae070a6-f4ec-4def-a383-d9cacc3f20a1',
      tenantId: 'g82wgnrvm-ywk9dggrrw8mtggy.pc-rnd',
    },
    // When shoppers use passwordless OTP login with one-click checkout, the system saves their shipping and payment information for faster checkout in the future.
    //   To maintain security, implement these safeguards:
    //   1. Captcha - Protects the passwordless login from bots.
    //   2. OTP for Email Changes - Verifies your identity before an email update, prevents accidental account lockouts from typos, and prevents unauthorized users from gaining access to saved payment methods.
    // To use One Click Checkout, enable the oneClickCheckout flag and configure private SLAS client. For more details, please
    // check https://github.com/SalesforceCommerceCloud/pwa-kit/releases/tag/v3.16.0
    oneClickCheckout: {
      enabled: false,
    },
    // Bonus product config
    pages: {
      cart: {
        groupBonusProductsWithQualifyingProduct: true,
      },
    },
    // Salesforce Payments configuration
    // Set enabled to true to enable Salesforce Payments (requires the Salesforce Payments feature toggle to be enabled on the Commerce Cloud instance).
    // Set enabled to false to disable Salesforce Payments on the storefront (the Commerce Cloud feature toggle is unaffected).
    // Set the sdkUrl and metadataUrl values to point to your Commerce Cloud instance host by replacing the [bm_or_vanity_host] placeholder with your Business Manager or vanity URL host name.
    //   sdkUrl:       'https://[bm_or_vanity_host]/on/demandware.static/Sites-Site/-/-/internal/jscript/sfp/v1/sfp.js'
    //   metadataUrl:  'https://[bm_or_vanity_host]/on/demandware.static/Sites-Site/-/-/internal/metadata/v1.json'
    sfPayments: {
      enabled: false,
      sdkUrl: '',
      metadataUrl: '',
    },
    // Google Cloud api config
    googleCloudAPI: {
      apiKey: process.env.GOOGLE_CLOUD_API_KEY,
    },
    // Contentful config — delivery token is intentionally public (read-only, published content only).
    // Preview token is read-only draft access; safe to include in the serialised client config for preview.
    contentful: {
      spaceId: process.env.CONTENTFUL_SPACE_ID,
      accessToken: process.env.CONTENTFUL_DELIVERY_TOKEN,
      environment: process.env.CONTENTFUL_ENVIRONMENT_ID,
      previewAccessToken: process.env.CONTENTFUL_PREVIEW_TOKEN || '',
    },
  },
  // This list contains server-side only libraries that you don't want to be compiled by webpack
  externals: [],
  // Page not found url for your app
  pageNotFoundURL: '/page-not-found',
  // Enables or disables building the files necessary for server-side rendering.
  ssrEnabled: true,
  // This list determines which files are available exclusively to the server-side rendering system
  // and are not available through the /mobify/bundle/ path.
  ssrOnly: ['ssr.js', 'ssr.js.map', 'node_modules/**/*.*'],
  // This list determines which files are available to the server-side rendering system
  // and available through the /mobify/bundle/ path.
  ssrShared: ['static/ico/favicon.ico', 'static/robots.txt', '**/*.js', '**/*.js.map', '**/*.json'],
  // Additional parameters that configure Express app behavior.
  ssrParameters: {
    ssrFunctionNodeVersion: '24.x',
    proxyConfigs: [
      {
        host: 'qmyt7hks.api.commercecloud.salesforce.com',
        path: 'api',
      },
      {
        host: 'bkzk-002.dx.commercecloud.salesforce.com',
        path: 'ocapi',
      },
    ],
  },
};

/**
 * Zimmermann country configuration — combines SCAPI-derived site/locale/
 * currency truth (countries.generated.ts, regenerate via
 * `npm run sync:regional-config`) with a hand-maintained overlay for the
 * fields Business Manager/SCAPI has no concept of: shipping country,
 * checkout ownership, and boutique region grouping.
 *
 * Used by: URL routing, IP-detection prompt, checkout redirect logic,
 * boutique location filtering, hreflang generation.
 *
 * When adding a country:
 *   1. Add it to config/sites.overlay.js (and e2e/fixtures/site.overlay.js
 *      if it needs e2e coverage), then run `npm run sync:regional-config`.
 *   2. Add its business-logic overlay entry below (shippingCountry,
 *      checkoutOwner, globalEPricing, boutiqueRegion).
 *   3. Ensure a compiled translation exists in overrides/app/static/translations/compiled/.
 *
 * Unresolved — do not hard-code:
 *   - NZ/Oceania currency routing
 *   - Denmark routing
 *   - China
 */

import { GENERATED_COUNTRIES } from './countries.generated';

/**
 * Who owns checkout for this site's domestic path.
 * For HK and ME, Global-e always owns checkout AND pricing from PDP onward.
 * For AU, US, GB, EU: SFCC owns domestic paths; Global-e takes over when the
 * user's shipping destination is outside the site's domestic market.
 */
export type CheckoutOwner = 'sfcc' | 'global-e' | 'hybrid';

export type CountryConfig = {
  /** URL path segment, e.g. 'au', 'us', 'fr-eu' */
  urlSlug: string;
  /** The real SFCC site this locale routes to */
  sfccSiteId: string;
  /** IETF locale used by PWA Kit / SFCC, e.g. 'en-AU' */
  locale: string;
  /** ISO 4217 currency code */
  currency: string;
  /** ISO 3166-1 alpha-2 shipping/tax country */
  shippingCountry: string;
  /**
   * Checkout owner for this site's domestic path.
   * Branch checkout AND pricing logic from this field at PDP/cart level —
   * not only at the checkout page.
   */
  checkoutOwner: CheckoutOwner;
  /**
   * When true, Global-e owns pricing, currency, and tax display from PDP
   * onward — do not render SFCC prices on these paths.
   */
  globalEPricing: boolean;
  /** Key used to filter boutique locations for this region */
  boutiqueRegion: string;
};

type CountryOverlayEntry = Pick<
  CountryConfig,
  'shippingCountry' | 'checkoutOwner' | 'globalEPricing' | 'boutiqueRegion'
>;

/**
 * Hand-maintained business/geo data, keyed the same way as
 * countries.generated.ts (URL slug; 'au' for the root/default site).
 *
 * 'en-ca' (US international) is defined here ready to go, but has no
 * matching entry in countries.generated.ts yet — it's excluded from the
 * final COUNTRIES export below until the ZimmermannUSIntl site is added to
 * config/sites.overlay.js (pending BM confirmation of the real site ID —
 * see .docs/planning/regionalConfigSyncPlan.md).
 */
const COUNTRY_OVERLAY: Record<string, CountryOverlayEntry> = {
  au: { shippingCountry: 'AU', checkoutOwner: 'sfcc', globalEPricing: false, boutiqueRegion: 'australia' },
  us: { shippingCountry: 'US', checkoutOwner: 'hybrid', globalEPricing: false, boutiqueRegion: 'usa' },
  'en-ca': { shippingCountry: 'CA', checkoutOwner: 'global-e', globalEPricing: true, boutiqueRegion: 'usa' }, // TBC — pending ZimmermannUSIntl
  uk: { shippingCountry: 'GB', checkoutOwner: 'sfcc', globalEPricing: false, boutiqueRegion: 'uk' },
  'en-eu': { shippingCountry: 'DE', checkoutOwner: 'sfcc', globalEPricing: false, boutiqueRegion: 'europe' }, // placeholder; shipping country resolved at checkout
  'fr-eu': { shippingCountry: 'FR', checkoutOwner: 'sfcc', globalEPricing: false, boutiqueRegion: 'europe' },
  'it-eu': { shippingCountry: 'IT', checkoutOwner: 'sfcc', globalEPricing: false, boutiqueRegion: 'europe' }, // placeholder; shipping country resolved at checkout
  'es-eu': { shippingCountry: 'ES', checkoutOwner: 'sfcc', globalEPricing: false, boutiqueRegion: 'europe' }, // placeholder; shipping country resolved at checkout
  'en-ch': { shippingCountry: 'CH', checkoutOwner: 'global-e', globalEPricing: true, boutiqueRegion: 'europe' }, // placeholder; Global-e resolves shipping country
  hk: { shippingCountry: 'HK', checkoutOwner: 'global-e', globalEPricing: true, boutiqueRegion: 'hong-kong' },
  'en-ae': { shippingCountry: 'AE', checkoutOwner: 'global-e', globalEPricing: true, boutiqueRegion: 'middle-east' },
};

/**
 * Keyed by urlSlug for O(1) lookup in routing/middleware.
 * AU is the exception: it has no URL prefix (root domain). Its key is 'au'
 * but urlSlug is '' — routing falls back to DEFAULT_COUNTRY_SLUG when no
 * prefix is detected.
 */
// Fail loud, not silent, if BM/the sync script produced a slug with no
// matching business-logic overlay — that means someone added a site to
// config/sites.overlay.js and ran `npm run sync:regional-config` without
// adding the corresponding COUNTRY_OVERLAY entry above. The reverse case
// (an overlay entry with no generated data yet, e.g. 'en-ca' pending the
// US-split site ID) is intentional and handled by the filter below instead.
const missingOverlays = Object.keys(GENERATED_COUNTRIES).filter((slug) => !(slug in COUNTRY_OVERLAY));
if (missingOverlays.length) {
  throw new Error(
    `countries.ts: config/sites.overlay.js has a site for slug(s) '${missingOverlays.join(', ')}' with no ` +
      `matching COUNTRY_OVERLAY entry — add shippingCountry/checkoutOwner/globalEPricing/boutiqueRegion for it.`,
  );
}

export const COUNTRIES: Record<string, CountryConfig> = Object.fromEntries(
  Object.entries(COUNTRY_OVERLAY)
    .filter(([slug]) => slug in GENERATED_COUNTRIES)
    .map(([slug, overlay]) => [
      slug,
      {
        urlSlug: slug === 'au' ? '' : slug,
        ...(GENERATED_COUNTRIES as Record<string, { sfccSiteId: string; locale: string; currency: string }>)[slug],
        ...overlay,
      },
    ]),
);

/** Fallback when no URL slug is present or IP detection fails. */
export const DEFAULT_COUNTRY_SLUG = 'au';

/** Lookup by ISO 3166-1 alpha-2 code — used by IP-detection prompt. */
export const COUNTRY_BY_SHIPPING_CODE: Record<string, CountryConfig> = Object.fromEntries(
  Object.values(COUNTRIES).map((c) => [c.shippingCountry, c]),
);

/*
 * Copyright (c) 2023, Salesforce, Inc.
 * All rights reserved.
 * SPDX-License-Identifier: BSD-3-Clause
 * For full license text, see the LICENSE file in the repo root or https://opensource.org/licenses/BSD-3-Clause
 */

// Hand-maintained routing overlay — the half of config/sites.js's data that
// Business Manager / SCAPI has no concept of: URL aliases and the
// sfccSiteId override used when multiple PWA sites share one real SFCC site
// (EU domestic's 4-locale split). Locale/currency truth instead comes from
